command:
// ==========================================
// ⚙️ LUNAS WIRKUNG: GEISTERFESSEL (ZERZAL)
//
// - Bannkegel bis 12 Schritt und 170°
// - Geister werden am Verlassen der Zone gehindert
// - Dauer: QS Minuten
// - Quelleffekt vollständig über Block 5
// - Zieleffekte direkt über Block 11
// - GM-Zonenbutton über Block 19.8
// - Wirkungsende über Block 6
// - Ziel-/Flächenbereinigung über Block 11
// ==========================================

(async function () {

    // +++ 1 - FRAMEWORK +++++++++++++++++++++++++++++++++++++++

    const frameworkUuid = "Compendium.dsk-havena-und-umland.makros.Macro.fHQ2OuDo3Fe3spBn";
    const frameworkFehlt =
        !globalThis.DSK?.Effekt?.Anwenden || !globalThis.DSK?.EffektEnde?.Register ||
        !globalThis.DSK?.QS?.Ermitteln || !globalThis.DSK?.Token?.Finde ||
        !globalThis.DSK?.Zone?.ApplyEffectsToSelected ||
        !globalThis.DSK?.GabenUI?.AnfrageKarteErstellen ||
        !globalThis.DSK?.GabenUI?.GMEffektBereich;

    if (frameworkFehlt) {
        const fwMacro = await fromUuid(frameworkUuid);
        if (!fwMacro) return ui.notifications.error("Luna sagt 🌙: Das DSK-Framework wurde nicht gefunden!");
        await fwMacro.execute();
        await new Promise(resolve => setTimeout(resolve, 250));
    }

    const DSK_FW = globalThis.DSK;

    if (
        !DSK_FW?.Effekt?.Anwenden || !DSK_FW?.EffektEnde?.Register ||
        !DSK_FW?.QS?.Ermitteln || !DSK_FW?.Token?.Finde ||
        !DSK_FW?.Zone?.ApplyEffectsToSelected ||
        !DSK_FW?.GabenUI?.AnfrageKarteErstellen ||
        !DSK_FW?.GabenUI?.GMEffektBereich
    ) return ui.notifications.error("Luna sagt 🌙: Das DSK-Framework wurde nicht vollständig geladen!");

    // +++ 2 - GRUNDDATEN ++++++++++++++++++++++++++++++++++++++

    const gabenName = "Geisterfessel", ahne = "Zerzal", vollerName = `${gabenName} (${ahne})`;
    const zielEffektName = "Zone - Geisterfessel", endeKey = "zerzalGeisterfessel";
    const endeText = "Die Energie der Skratglyphen erlischt, und die Geisterfessel löst sich auf.";
    const iconBild = DSK_FW.Symbol(ahne);

    DSK_FW.EffektEnde.Register(endeKey, vollerName, endeText);

    // +++ 3 - HILFSFUNKTIONEN +++++++++++++++++++++++++++++++++

    const raeumeQSAuf = async actor => {
        if (actor?.getFlag("world", "letzteGabenQS") !== undefined) await actor.unsetFlag("world", "letzteGabenQS");
        if (actor?.getFlag("world", "letzteGabenMessageId") !== undefined) await actor.unsetFlag("world", "letzteGabenMessageId");
    };

    const findeQuellEffekte = actor => (actor?.effects || []).filter(effect =>
        effect.getFlag("dsk", "isZoneSource") === true &&
        effect.getFlag("dsk", "isGeisterfessel") === true &&
        effect.getFlag("dsk", "casterUuid") === actor.uuid
    );

    // +++ 4 - WIRKENDER UND QS ++++++++++++++++++++++++++++++++

    const safeTestData = typeof testData !== "undefined" ? testData : null;
    const safeActor = typeof actor !== "undefined" ? actor : null;

    let casterActor =
        safeTestData?.actor ||
        (safeTestData?.speaker?.token ? canvas.tokens.get(safeTestData.speaker.token)?.actor : null) ||
        safeActor || canvas.tokens.controlled[0]?.actor || game.user.character || null;

    if (!casterActor) {
        casterActor =
            canvas.tokens.placeables.map(token => token.actor)
                .find(actor => actor?.getFlag("world", "letzteGabenQS") !== undefined) ||
            game.actors.find(actor => actor.getFlag("world", "letzteGabenQS") !== undefined) ||
            null;
    }

    if (!casterActor) return ui.notifications.warn("Luna sagt 🌙: Kein Wirkender gefunden!");

    if (!game.user.isGM && !casterActor.isOwner) {
        return ui.notifications.warn("Luna sagt 🌙: Du besitzt keine ausreichenden Rechte für diesen Akteur!");
    }

    const casterToken = DSK_FW.Token.Finde(casterActor);
    if (!casterToken) return ui.notifications.warn("Luna sagt 🌙: Kein Token des Wirkenden gefunden!");

    const casterName = DSK_FW.ResolveTokenName(casterActor);
    const qs = DSK_FW.QS.Ermitteln({
        actor: casterActor, gabenName,
        suchbegriffe: ["Geisterfessel Probe", "Geisterfessel"],
        testDataObj: safeTestData, fallback: 0, protokollieren: true
    });

    if (qs <= 0) {
        await DSK_FW.GabenUI.AnfrageKarteErstellen({
            gabenName: vollerName, ahne,
            beschreibung: "Die Zone der Geisterfessel konnte nicht erschaffen werden.",
            wirkender: casterName, ziele: [],
            misserfolge: [{ name: casterName, grund: "Probe fehlgeschlagen" }],
            gmBereich: false, angewendet: true, erfolgreich: false,
            anfragenderUserId: game.user.id
        });

        await raeumeQSAuf(casterActor);
        return;
    }

    // +++ 5 - GEISTERFESSEL KONFIGURIEREN +++++++++++++++++++++

    const einstellungen = await foundry.applications.api.DialogV2.wait({
        window: { title: "Geisterfessel konfigurieren" },
        position: { width: 420 },
        content: `<form><div style="font-family:'Signika',sans-serif;">
            ${DSK_FW.UI.Header(vollerName, iconBild)}
            <div class="dskbox2" style="margin-top:10px;">
                <p style="font-size:.95em;line-height:1.35;margin-bottom:10px;">
                    Lege die Maße für die Geisterfessel fest.
                </p>
                <div style="margin-bottom:8px;">
                    <label style="font-weight:bold;font-size:.9em;">Länge (max. 12 Schritt):</label>
                    <input type="number" name="laenge" value="12" min="1" max="12"
                        style="width:100%;padding:4px;margin-top:4px;">
                </div>
                <div>
                    <label style="font-weight:bold;font-size:.9em;">Öffnungswinkel (max. 170°):</label>
                    <input type="number" name="winkel" value="60" min="10" max="170"
                        style="width:100%;padding:4px;margin-top:4px;">
                </div>
            </div>
        </div></form>`,
        buttons: [
            {
                action: "ok", label: "Weiter", icon: "fas fa-arrow-right", default: true,
                callback: event => {
                    const data = new FormData(event.target.closest("form"));
                    return {
                        laenge: Math.min(12, Math.max(1, Number(data.get("laenge")) || 12)),
                        winkel: Math.min(170, Math.max(10, Number(data.get("winkel")) || 60))
                    };
                }
            },
            { action: "cancel", label: "Abbrechen", icon: "fas fa-times", callback: () => null }
        ],
        rejectClose: false
    });

    if (!einstellungen) {
        await raeumeQSAuf(casterActor);
        return ui.notifications.warn("Luna sagt 🌙: Fessel abgebrochen.");
    }

    const radiusSchritt = einstellungen.laenge, kegelWinkel = einstellungen.winkel;

    // +++ 6 - GEISTERFESSEL PLATZIEREN ++++++++++++++++++++++++

    const confirmPosition = () => foundry.applications.api.DialogV2.wait({
        window: { title: "Geisterfessel platzieren" },
        position: { width: 420 },
        content: `<div style="font-family:'Signika',sans-serif;">
            ${DSK_FW.UI.Header(vollerName, iconBild)}
            <div class="dskbox2" style="margin-top:10px;">
                <p style="font-size:.95em;line-height:1.35;">
                    Verschiebe und drehe die Geisterfessel
                    (${radiusSchritt} Schritt, ${kegelWinkel}°) auf der Karte.
                    <br><br>Klicke danach auf <b>Position bestätigen</b>.
                </p>
            </div>
        </div>`,
        buttons: [
            { action: "ok", label: "Position bestätigen", icon: "fas fa-check", default: true, callback: () => true },
            { action: "cancel", label: "Abbrechen", icon: "fas fa-times", callback: () => false }
        ],
        rejectClose: false
    });

    ui.notifications.info("Luna sagt 🌙: Platziere und richte die Geisterfessel aus.");

    const [templateDoc] = await canvas.scene.createEmbeddedDocuments("MeasuredTemplate", [{
        t: "cone", user: game.user.id,
        distance: radiusSchritt, direction: 0, angle: kegelWinkel,
        x: casterToken.center.x, y: casterToken.center.y,
        fillColor: game.user.color || "#000000",
        fillAlpha: 0.15, lineThickness: 1, hidden: false
    }]);

    if (!templateDoc) {
        await raeumeQSAuf(casterActor);
        return ui.notifications.error("Luna sagt 🌙: Die Geisterfessel konnte nicht erstellt werden!");
    }

    try { canvas.templates.activate(); } catch {}
    const positionBestaetigt = await confirmPosition();
    try { canvas.tokens.activate(); } catch {}

    if (!positionBestaetigt) {
        await templateDoc.delete();
        await raeumeQSAuf(casterActor);
        return ui.notifications.warn("Luna sagt 🌙: Fessel abgebrochen.");
    }

    // +++ 7 - WIRKUNGSDATEN +++++++++++++++++++++++++++++++++++

    const dauerMinuten = qs, dauerSekunden = dauerMinuten * 60;
    const dauerText = `${dauerMinuten} Minute${dauerMinuten > 1 ? "n" : ""} (${qs} QS)`;

    const basisBeschreibung =
        `Das Zerzalkind erschafft eine Zone der Geisterfessel ` +
        `(${radiusSchritt} Schritt, ${kegelWinkel}°).` +
        `<br><br>• Geister im Inneren werden festgehalten und daran gehindert, die Zone zu verlassen.`;

    const wirkungsende = {
        sfName: endeKey, basisEffektName: vollerName,
        beschreibungFuerEnde: endeText
    };

    // +++ 8 - ALTE EIGENE GEISTERFESSEL ERSETZEN ++++++++++++++

    const alteQuellEffekte = findeQuellEffekte(casterActor);
    if (alteQuellEffekte.length) {
        await casterActor.deleteEmbeddedDocuments(
            "ActiveEffect",
            alteQuellEffekte.map(effect => effect.id)
        );
    }

    // +++ 9 - QUELLEFFEKT DIREKT ÜBER BLOCK 5 +++++++++++++++++

    const quellEffekt = await DSK_FW.Effekt.Anwenden({
        name: vollerName, ahne,
        beschreibung: `${basisBeschreibung}<br><br><b>Wirkungsdauer:</b> ${dauerText}`,
        gabeZiel: "", qs, ziel: casterActor, changes: [],
        duration: { seconds: dauerSekunden, startTime: game.time.worldTime },
        showIcon: 1,
        flags: { dsk: {
            isZoneSource: true, isGeisterfessel: true,
            wirkungsendeUeberBlock6: true,
            templateId: templateDoc.id, templateUuid: templateDoc.uuid,
            zielEffektName, casterEffektName: vollerName,
            casterUuid: casterActor.uuid, casterName,
            ahne, qs, radiusSchritt, kegelWinkel,
            wirkungsende
        }}
    });

    if (!quellEffekt) {
        await templateDoc.delete();
        await raeumeQSAuf(casterActor);
        return ui.notifications.error("Luna sagt 🌙: Der Geisterfessel-Quelleffekt konnte nicht angelegt werden!");
    }

    // +++ 10 - ZIELEFFEKT-DATEN FÜR BLOCK 11 ++++++++++++++++++
    //
    // WICHTIG:
    // Block 11 erstellt diesen Zieleffekt direkt.
    // Keine Übergabe an Block 5 und keine Zielkategorieprüfung.

    const effektData = {
        img: iconBild, icon: iconBild, type: "base", showIcon: 1,
        duration: { seconds: dauerSekunden, startTime: game.time.worldTime },
        changes: [], statuses: [],
        description: "Der Geist wird daran gehindert, die Zone der Geisterfessel zu verlassen.",
        flags: { dsk: {
            isZoneTarget: true, isGeisterfesselTarget: true,
            casterUuid: casterActor.uuid, casterName, qs,
            value: 1, max: 6,
            wirkungsende
        }}
    };

    // +++ 11 - GEMEINSAME KARTE ÜBER BLOCK 19.8 +++++++++++++++

    const nachricht = await DSK_FW.GabenUI.AnfrageKarteErstellen({
        gabenName: vollerName, ahne, beschreibung: basisBeschreibung,
        wirkender: casterName, ziele: [], misserfolge: [], dauerText,
        gmBereich: true, angewendet: false, erfolgreich: false,
        gmEffekt: {
            templateId: templateDoc.id, zielEffektName, ahne, effektData,
            hinweis: "Wähle die betroffenen Geister auf der Karte aus."
        },
        anfragenderUserId: game.user.id
    });

    if (!nachricht) {
        // Block 11 entfernt durch das Löschen des Quelleffekts auch die Fläche.
        await quellEffekt.delete();
        await raeumeQSAuf(casterActor);
        return ui.notifications.error("Luna sagt 🌙: Die Geisterfessel-Karte konnte nicht erstellt werden!");
    }

    // +++ 12 - QUELLEFFEKT KONTROLLIEREN ++++++++++++++++++++++

    const endeDaten = quellEffekt.getFlag("dsk", "wirkungsende");

    const effektErfolgreich =
        (quellEffekt.name || quellEffekt.label || "") === vollerName &&
        quellEffekt.getFlag("dsk", "isZoneSource") === true &&
        quellEffekt.getFlag("dsk", "isGeisterfessel") === true &&
        quellEffekt.getFlag("dsk", "templateId") === templateDoc.id &&
        quellEffekt.getFlag("dsk", "templateUuid") === templateDoc.uuid &&
        quellEffekt.getFlag("dsk", "zielEffektName") === zielEffektName &&
        quellEffekt.getFlag("dsk", "casterUuid") === casterActor.uuid &&
        endeDaten?.sfName === endeKey &&
        endeDaten?.basisEffektName === vollerName &&
        endeDaten?.beschreibungFuerEnde === endeText;

    if (!effektErfolgreich) {
        await quellEffekt.delete();
        await raeumeQSAuf(casterActor);
        return ui.notifications.error("Luna sagt 🌙: Geisterfessel wurde nicht vollständig angelegt!");
    }

    // +++ 13 - QS AUFRÄUMEN +++++++++++++++++++++++++++++++++++

    await raeumeQSAuf(casterActor);

}).call(this);
